using System.ComponentModel;
using System.Globalization;
using Avalonia.Data.Converters;

namespace TestLoom.App.Services;

/// <summary>Servizio di localizzazione IT/EN/FR: singleton con notifica di cambiamento in stile indicizzatore.
/// Il binding diretto "Path=[chiave]" si legge correttamente al primo render ma Avalonia non lo rinfresca
/// live sul solo "Item[]" (verificato: la sidebar — legata con MultiBinding esplicita su Lingua — cambiava
/// lingua dal vivo, ma testo/bottoni legati con Path=[chiave] restavano fermi alla lingua di apertura pagina
/// finché non venivano ricreati). Il binding corretto va quindi fatto su "Lingua" (proprietà nominata, che
/// notifica sempre in modo affidabile) passando attraverso <see cref="TraduciConverter"/> con la chiave come
/// ConverterParameter — vedi quel commento per il pattern XAML completo. Le etichette degli enum
/// (EnumDisplay.Label) leggono direttamente Instance.Lingua invece di passare da qui, perché sono funzioni
/// pure senza un binding diretto a rinfrescare.</summary>
public sealed partial class LocalizationService : INotifyPropertyChanged
{
    public static LocalizationService Instance { get; } = new();

    public event PropertyChangedEventHandler? PropertyChanged;

    /// <summary>Lingue dell'interfaccia: it, en, fr. Qualsiasi altro valore (es. config manomesso) ricade su "it".</summary>
    public static string NormalizzaLingua(string? valore) => valore is "en" or "fr" ? valore : "it";

    private string _lingua = "it";
    public string Lingua
    {
        get => _lingua;
        set
        {
            var nuova = NormalizzaLingua(value);
            if (_lingua == nuova) return;
            _lingua = nuova;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Lingua)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(EItaliano)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(EInglese)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(EFrancese)));
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        }
    }

    public bool EItaliano => Lingua == "it";

    public bool EInglese => Lingua == "en";

    public bool EFrancese => Lingua == "fr";

    public string this[string chiave] => Traduci(chiave);

    /// <summary>Ricerca per chiave: francese se la lingua è "fr" e la chiave ha una traduzione francese;
    /// altrimenti inglese (anche per "fr" senza traduzione); chiave sconosciuta: la chiave stessa.</summary>
    public string Traduci(string chiave)
    {
        if (!Dizionario.TryGetValue(chiave, out var coppia)) return chiave;
        if (Lingua == "fr" && Francese.TryGetValue(chiave, out var francese)) return francese;
        return Lingua == "it" ? coppia.It : coppia.En;
    }

    /// <summary>Testo per la lingua corrente per i messaggi composti inline (senza chiave di dizionario).</summary>
    public string Scegli(string it, string en, string fr) => Lingua switch
    {
        "fr" => fr,
        "en" => en,
        _ => it,
    };

