        ["AvvisoVolumeGrande"] = ("Nessun filtro attivo su un archivio ampio: l'export includerà tutti i test. Procedi pure, ma potrebbe richiedere qualche secondo in più.", "No filter active on a large archive: the export will include every test. Go ahead, it may just take a bit longer."),
