        ["MatriceLegendaNonTestato"] = ("Non testato", "Not tested"),
        ["MatriceLegendaMisto"] = ("Misto: più stati nella cella", "Mixed: several states in the cell"),
        ["MatriceTooltipModalitaStato"] = ("Stato = ultimo esito di ogni combinazione Funzionalità × componente × Prodotto. Se la cella raccoglie combinazioni con esiti diversi, mostra Misto e il conteggio per esito. I valori manuali partecipano secondo la loro data; N.A. è escluso.", "Status = the latest outcome for each Function × component × Product combination. If a cell groups combinations with different outcomes, it shows Mixed and the count for each outcome. Manual values are included by date; N/A is excluded."),
        ["MatriceTooltipModalitaStatoPercentuale"] = ("Stato % = distribuzione percentuale dell’ultimo esito per combinazione Funzionalità × componente × Prodotto; ogni combinazione conta una volta. I valori manuali correnti sono inclusi; N.A. è escluso. Le sigle indicano: OK = Conforme; NOK = Non conforme; dev. = Conforme con deviazioni; da eseg. = Da eseguire; non test. = Non testato; ! = da decidere.", "Status % = percentage distribution of the latest outcome per Function × component × Product combination; each combination counts once. Current manual values are included; N/A is excluded. Abbreviations: OK = Pass; NOK = Fail; dev. = Pass with deviations; to run = To be executed; not tested = Not tested; ! = To decide."),
        ["MatriceTooltipModalitaTestPercentuale"] = ("Test % = distribuzione percentuale dello stato corrente di ogni TestCase distinto, contato una sola volta. I valori manuali e gli snapshot di stato importati dagli UnitLogger sono esclusi. Le sigle indicano: OK = Conforme; NOK = Non conforme; dev. = Conforme con deviazioni; da eseg. = Da eseguire; non test. = Non testato; ! = da decidere.", "Test % = percentage distribution of the current status of each distinct TestCase, counted once. Manual values and status-only snapshots imported from UDTs are excluded. Abbreviations: OK = Pass; NOK = Fail; dev. = Pass with deviations; to run = To be executed; not tested = Not tested; ! = To decide."),
        ["MatriceTooltipValoreVuoto"] = ("Nessuna combinazione o nessun test applicabile in questa cella.", "No applicable combination or Test exists in this cell."),
        ["MatriceTooltipValoreConforme"] = ("L’ultimo esito è Conforme.", "The latest outcome is Pass."),
