        ["MatriceTooltipValoreDeviazioni"] = ("L’ultimo esito è Conforme con deviazioni.", "The latest outcome is Pass with deviations."),
        ["MatriceTooltipValoreDaEseguire"] = ("La combinazione è prevista ma non ha ancora un esito eseguito.", "The combination is planned but has no completed outcome yet."),
        ["MatriceTooltipValoreNonTestato"] = ("Non è disponibile un esito di test per le combinazioni incluse.", "No test outcome is available for the included combinations."),
        ["MatriceTooltipValoreDaDecidere"] = ("Manca la decisione Master che indica se la combinazione è applicabile.", "The Master still needs to decide whether this combination applies."),
        ["MatriceTooltipValoreMisto"] = ("La cella raggruppa più combinazioni con stati diversi: {0}.", "The cell groups combinations with different statuses: {0}."),
        ["MatriceTooltipMistoGenerico"] = ("vedi il riepilogo della cella", "see the cell summary"),
        ["MatriceTooltipValoreNA"] = ("N.A. = cella esclusa dal calcolo delle percentuali.", "N/A = cell excluded from percentage calculations."),
        ["MatriceTooltipManuale"] = ("Valore manuale del Master. La cella mostra l’evento più recente.", "Manual value entered by the Master. The cell shows the latest event."),
        ["MatriceTooltipManualeSuperato"] = ("Un Test più recente ha sostituito il valore manuale.", "A newer Test superseded the manual value."),
        ["HomeTooltipConformita"] = ("Stato % mostra l’ultimo esito per ogni combinazione Funzionalità × componente × Prodotto; Test % conta lo stato corrente di ogni TestCase una volta. In entrambi i casi i valori mostrano le quote Conforme, Non conforme, Conforme con deviazioni, Da eseguire, Non testato e Da decidere, sulla base dei filtri attivi.", "Status % shows the latest outcome for each Function × component × Product combination; Test % counts the current status of each TestCase once. Both show the shares of Pass, Fail, Pass with deviations, To be executed, Not tested, and To decide, using the active filters."),
        ["HomeTooltipGraficoEsiti"] = ("Esiti: Conforme = test superato; Non conforme = test non superato; Conforme con deviazioni = superato con deviazioni; Da eseguire = prova pianificata/non completata; Non applicabile = escluso; Da rivedere e Non eseguito N.A. sono valori legacy. I grafici sono immagini: il tooltip descrive l’intero grafico, non il singolo spicchio.", "Outcomes: Pass = test passed; Non-conforming = test failed; Pass with deviations = passed with deviations; To be executed = planned/incomplete test; Not applicable = excluded; To review and Not executed N/A are legacy values. Charts are images: this tooltip describes the whole chart, not an individual slice."),
        ["HomeTooltipEsitoNonTestato"] = ("Non testato: non è disponibile un esito corrente per questo Test.", "Not tested: no current outcome is available for this Test."),
        ["HomeTooltipEsitoDaEseguire"] = ("Da eseguire: la prova è pianificata o non ancora completata.", "To be executed: the test is planned or not yet completed."),
        ["HomeTooltipEsitoConforme"] = ("Conforme: l’ultimo esito del Test è conforme.", "Pass: the latest Test outcome is conforming."),
        ["HomeTooltipEsitoNonConforme"] = ("Non conforme: l’ultimo esito del Test non è conforme.", "Non-conforming: the latest Test outcome failed."),
        ["HomeTooltipEsitoDeviazioni"] = ("Conforme con deviazioni: esito conforme con deviazioni registrate.", "Pass with deviations: the outcome passes with recorded deviations."),
        ["HomeTooltipEsitoNA"] = ("Non applicabile: il Test/operazione è escluso dai conteggi di esecuzione.", "Not applicable: the Test/operation is excluded from execution counts."),
        ["HomeTooltipEsitoLegacyNA"] = ("Non eseguito N.A.: stato storico non proposto per i nuovi test.", "Not executed N/A: a legacy status no longer offered for new tests."),
        ["HomeTooltipEsitoDaRivedere"] = ("Da rivedere: stato storico da riesaminare.", "To review: a legacy status that should be reviewed."),
