        ["TestInclusiFmt"] = ("{0} test inclusi", "{0} tests included"),
        ["AnteprimaLimitataFmt"] = ("La tabella mostra gli ultimi {0} test su {1}. Matrice ed export usano tutti i risultati filtrati.", "The table shows the latest {0} tests out of {1}. The matrix and exports use all filtered results."),
        ["ColEsito"] = ("Esito", "Outcome"),
        ["ColData"] = ("Data", "Date"),
        // Export Excel: fogli "Filtri" e "Origine" della vista (6.4.3)
        ["OrigineFoglioFiltri"] = ("Filtri", "Filters"),
        ["OrigineFoglioOrigine"] = ("Origine", "Source data"),
        ["OrigineNota"] = ("Un dato filtrato per prodotto/componente/funzionalità. \"Determina lo stato\" = Sì se la riga contribuisce alla matrice: vincitore o previsione per Stato/Percentuale; tutti i Test per Test%; tentativi ammessi per Tempo. Le altre righe sono aggiuntive e possono essere escluse secondo il limite indicato. Con più dimensioni una riga può ricadere in più celle; Esito mostra lo stato della combinazione. \"N.A.\" = tutte le celle contenenti la riga sono marcate N.A. I Test UnitLogger seguono la selezione della vista.", "One filtered datum per product/component/functionality. \"Determines status\" = Yes when the row contributes to the matrix: winner or planned representative for Status/Percentage; every Test for Test%; accepted attempts for Time. Other rows are additional and may be omitted at the stated limit. With multiple dimensions a row may fall into several cells; Outcome shows the combination status. \"N.A.\" = every cell containing the row is marked N.A. UnitLogger Tests follow the view selection."),
        ["PdfMostratiRequisitiFmt"] = ("Mostrati {0} requisiti su {1} (limite del PDF).", "Showing {0} of {1} requirements (PDF limit)."),
