        ["ImportReportUdtFmt"] = ("Report import log UnitLogger: campi importati {0} · mancanti {1} · non configurati {2} · valori scritti {3}. Nulla è salvato finché non premi Salva.", "UnitLogger log import report: fields imported {0} · missing {1} · not configured {2} · values written {3}. Nothing is saved until you press Save."),
