        ["DtcAnnullaRiscritturaFallitaFmt"] = ("Impossibile ripristinare l'archivio guasto del requisito {0} ({1}): la modifica resta aperta, riprova ad annullare o salva.", "Cannot restore the fault archive of requirement {0} ({1}): editing stays open, retry Cancel or Save."),
        ["MasterDatiAggiornatiDuranteModifica"] = ("Dati aggiornati da un'altra operazione: le modifiche digitate sono conservate. Ricaricare dopo il salvataggio.", "Data was updated by another operation: your typed changes are kept. Reload after saving."),
