        ["ImportUdtMainFileTipo"] = ("Log principale UnitLogger (udt_main)", "UnitLogger main logs (udt_main)"),
        ["ImportaLogUdtWuBtn"] = ("Importa log WU...", "Import WU log..."),
        ["ImportaLogUdtMainBtn"] = ("Importa log main...", "Import main log..."),
        ["ImportExcelGuidaTestoFmt"] = ("Prepara un file .xlsx o .xls con una riga per elemento. L'import legge le colonne in base alla posizione: le intestazioni possono avere qualsiasi testo.\n\n{0}\n\nLe righe vuote vengono ignorate; gli elementi già presenti in genere non vengono sovrascritti. Per componente e Funzionalità le associazioni vengono invece aggiunte. Dopo questo avviso potrai scegliere il file, il foglio e la riga delle intestazioni.", "Prepare an .xlsx or .xls file with one row per item. Columns are read by position, so header text can be anything.\n\n{0}\n\nBlank rows are ignored; existing items are generally not overwritten. component and Functionality associations are added instead. After this notice you can choose the file, sheet, and header row."),
        ["ImportDtcGuidaTestoFmt"] = ("Prepara il file guasto nel formato indicato. Sono accettati Excel (.xlsx/.xls), CSV e TXT.\n\n{0}\n\nPer Excel scegli il foglio e la riga da usare come intestazione: quella riga viene esclusa e i dati successivi sono letti per posizione. CSV/TXT possono avere intestazioni riconosciute (Requisito, guasto, componente, Prodotto) oppure essere senza intestazione; accettano il separatore punto e virgola. Dopo questo avviso potrai scegliere il file.", "Prepare the fault file in the format shown. Excel (.xlsx/.xls), CSV, and TXT are supported.\n\n{0}\n\nFor Excel, choose the sheet and header row: that row is excluded, and subsequent data is read by position. CSV/TXT may use recognized headers (Requirement, fault, component, Product) or be headerless; semicolon separators are supported. After this notice you can choose the file."),
        ["ImportExcelSchemaEcu"] = ("Colonne: A = Nome componente; B = prodotti associati, separati da virgola o punto e virgola.", "Columns: A = component name; B = associated products, separated by commas or semicolons."),
        ["ImportExcelSchemaGamma"] = ("Colonne: A = Nome Famiglia.", "Columns: A = Famiglia name."),
        ["ImportExcelSchemaVeicoli"] = ("Colonne: A = Nome prodotto o banco; B = Famiglia.", "Columns: A = product or bench name; B = Famiglia."),
        ["ImportExcelSchemaFunzionalita"] = ("Colonne: A = Nome; B = Categoria; C = Componenti associati (nomi separati da virgola o punto e virgola, oppure * per tutti i componenti); D = (facoltativa) prodotti per componente: componente => V1, V2; componente2 => V3 (oppure *, nessuna restrizione).", "Columns: A = name; B = category; C = associated Components (names separated by commas or semicolons, or * for all Components); D = (optional) products per component: component => V1, V2; component2 => V3 (or *, no restriction)."),
        ["ImportExcelSchemaRequisiti"] = ("Colonne: A = Id; B = Testo; C = Applicabile banco; D = Applicabile prodotto.", "Columns: A = ID; B = text; C = applicable to bench; D = applicable to product."),
        ["ImportExcelSchemaStrumenti"] = ("Colonne: A = Nome strumento.", "Columns: A = tool name."),
        ["ImportExcelSchemaDtcRequisiti"] = ("Ordine delle colonne dati: A = Requisito, B = guasto, C = componente, D = Prodotto facoltativa. Se importi un singolo requisito puoi omettere la colonna Requisito: A = guasto, B = componente. Per CSV/TXT vale lo stesso ordine.", "Data column order: A = Requirement, B = fault, C = component, D = optional Product. When importing a single requirement, you can omit the Requirement column: A = fault, B = component. The same order applies to CSV/TXT."),
        ["Continua"] = ("Continua", "Continue"),
        ["ImportExcelFoglioLabel"] = ("Foglio", "Sheet"),
        ["ImportExcelRigaLabel"] = ("Riga di intestazione", "Header row"),
        ["ImportExcelRigaAiuto"] = ("Il numero della riga con i nomi delle colonne (es. \"Id\", \"Testo\"). I dati vengono letti a partire dalla riga successiva.", "The row number containing the column labels (e.g. \"Id\", \"Text\"). Data is read starting from the next row."),

