/// <summary>Legge sempre la chiave dal ConverterParameter e ignora il value in ingresso: il binding va fatto
/// su LocalizationService.Instance.Lingua (Path=Lingua) proprio perché è quella la proprietà che notifica in
/// modo affidabile — il value passato qui è quindi solo il "trigger" del ricalcolo, mai il dato mostrato.
/// Pattern XAML: Text="{Binding Source={x:Static services:LocalizationService.Instance}, Path=Lingua,
/// Converter={x:Static services:TraduciConverter.Instance}, ConverterParameter=NomeChiave}".</summary>
public sealed class TraduciConverter : IValueConverter
{
    public static readonly TraduciConverter Instance = new();
