/// <summary>
/// Presentation-only translation for existing TICKET report filter sentinels.
/// Stored filter keys remain stable (Tutti/Tutte/Apertura/Chiusura), so changing
/// the UI language cannot silently change query semantics or saved filters.
/// </summary>
public sealed class PolarionFilterLabelConverter : IValueConverter
{
    public static readonly PolarionFilterLabelConverter Instance = new();

    public object Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        var loc = LocalizationService.Instance;
        return value switch
        {
            "Tutti" => loc.Scegli("Tutti", "All", "Tous"),
            "Tutte" => loc.Scegli("Tutte", "All", "Toutes"),
            "Apertura" => loc.Scegli("Apertura", "Opened", "Ouverture"),
            "Chiusura" => loc.Scegli("Chiusura", "Closed", "Clôture"),
            _ => value?.ToString() ?? ""
        };
    }

    public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture) =>
        throw new NotSupportedException();
}

/// <summary>Re-evaluates the filter label when the UI language changes.</summary>
public sealed class PolarionFilterLocalizedConverter : IMultiValueConverter
{
    public static readonly PolarionFilterLocalizedConverter Instance = new();

    public object Convert(IList<object?> values, Type targetType, object? parameter, CultureInfo culture) =>
        PolarionFilterLabelConverter.Instance.Convert(values.Count > 0 ? values[0] : null,
            targetType, parameter, culture);
}
